#!/usr/bin/env powershell\n<#\n.SYNOPSIS\n    Verify and manage Execution Engine Windows service\n\n.DESCRIPTION\n    Provides commands to check service status, view logs, restart, and troubleshoot\n    the Execution Engine Windows service (NSSM-based).\n\n.PARAMETER Command\n    'status', 'logs', 'restart', 'stop', 'start', 'remove', or 'help'\n\n.EXAMPLE\n    .\\service.ps1 status\n    .\\service.ps1 logs\n    .\\service.ps1 restart\n#>\n\nparam(\n    [string]$Command = \"status\"\n)\n\n$ServiceName = \"ExecutionEngine\"\n$NssmExe = \"nssm\"\n$LogDir = \"logs\"\n\nfunction Show-Help {\n    Write-Host @\"\nExecution Engine Service Manager\n\nUsage: .\\service.ps1 <command>\n\nCommands:\n  status      Check service status\n  logs        View recent service logs (live)\n  logs-err    View error log file\n  logs-out    View output log file\n  restart     Restart the service\n  start       Start the service\n  stop        Stop the service (graceful)\n  edit        Edit service configuration (UI)\n  remove      Uninstall service (requires reinstall with install_service.ps1)\n  help        Show this help\n\nExamples:\n  .\\service.ps1 status          # Check if running\n  .\\service.ps1 logs            # Monitor logs in real-time\n  .\\service.ps1 restart         # Restart service\n  .\\service.ps1 logs-err        # View error log file\n\nFor full deployment documentation:\n  https://github.com/amfredfred/execution-engine/docs/deployment.md\n\"@\n}\n\nfunction Show-Status {\n    Write-Host \"`n=== Execution Engine Service Status ===\"\n    Write-Host \"\"\n    \n    $status = & $NssmExe status $ServiceName 2>&1\n    Write-Host \"Service Status: $status\"\n    \n    # Check if logs directory exists\n    if (Test-Path $LogDir) {\n        Write-Host \"Log Directory: $(Resolve-Path $LogDir)\"\n        \n        # Show log file sizes\n        $errLog = Join-Path $LogDir \"service_stderr.log\"\n        $outLog = Join-Path $LogDir \"service_stdout.log\"\n        \n        if (Test-Path $errLog) {\n            $size = (Get-Item $errLog).Length / 1MB\n            Write-Host \"Error Log Size: $([math]::Round($size, 2)) MB\"\n        }\n        if (Test-Path $outLog) {\n            $size = (Get-Item $outLog).Length / 1MB\n            Write-Host \"Output Log Size: $([math]::Round($size, 2)) MB\"\n        }\n    } else {\n        Write-Host \"Log Directory: Not found (create with: New-Item -ItemType Directory -Path logs)\"\n    }\n    \n    Write-Host \"\"\n    Write-Host \"Useful next steps:\"\n    Write-Host \"  View logs:    .\\service.ps1 logs\"\n    Write-Host \"  Check errors: .\\service.ps1 logs-err\"\n    Write-Host \"  Restart:      .\\service.ps1 restart\"\n    Write-Host \"\"\n}\n\nfunction Show-Logs {\n    $errLog = Join-Path $LogDir \"service_stderr.log\"\n    if (-not (Test-Path $errLog)) {\n        Write-Error \"Error log not found: $errLog\"\n        return\n    }\n    Write-Host \"Monitoring error log (Ctrl+C to stop)...\"\n    Write-Host \"File: $errLog`n\"\n    Get-Content $errLog -Tail 50 -Wait\n}\n\nfunction Show-LogsErr {\n    $errLog = Join-Path $LogDir \"service_stderr.log\"\n    if (-not (Test-Path $errLog)) {\n        Write-Error \"Error log not found: $errLog\"\n        return\n    }\n    Write-Host \"Last 100 lines of error log:\"\n    Write-Host \"\"\n    Get-Content $errLog -Tail 100\n}\n\nfunction Show-LogsOut {\n    $outLog = Join-Path $LogDir \"service_stdout.log\"\n    if (-not (Test-Path $outLog)) {\n        Write-Error \"Output log not found: $outLog\"\n        return\n    }\n    Write-Host \"Last 100 lines of output log:\"\n    Write-Host \"\"\n    Get-Content $outLog -Tail 100\n}\n\nfunction Restart-Service {\n    Write-Host \"Restarting $ServiceName...\"\n    & $NssmExe restart $ServiceName\n    Start-Sleep -Seconds 2\n    $status = & $NssmExe status $ServiceName 2>&1\n    Write-Host \"Service status: $status\"\n}\n\nfunction Start-Service {\n    Write-Host \"Starting $ServiceName...\"\n    & $NssmExe start $ServiceName\n    Start-Sleep -Seconds 2\n    $status = & $NssmExe status $ServiceName 2>&1\n    Write-Host \"Service status: $status\"\n}\n\nfunction Stop-Service {\n    Write-Host \"Stopping $ServiceName...\"\n    & $NssmExe stop $ServiceName confirm\n    Start-Sleep -Seconds 2\n    $status = & $NssmExe status $ServiceName 2>&1\n    Write-Host \"Service status: $status\"\n}\n\nfunction Edit-Service {\n    Write-Host \"Opening service configuration UI...\"\n    & $NssmExe edit $ServiceName\n}\n\nfunction Remove-Service {\n    Write-Host \"Removing $ServiceName...\"\n    & $NssmExe remove $ServiceName confirm\n    Write-Host \"Service removed.\"\n    Write-Host \"To reinstall, run: powershell -ExecutionPolicy Bypass -File install_service.ps1\"\n}\n\n# Main dispatch\nswitch ($Command.ToLower()) {\n    \"status\" { Show-Status }\n    \"logs\" { Show-Logs }\n    \"logs-err\" { Show-LogsErr }\n    \"logs-out\" { Show-LogsOut }\n    \"restart\" { Restart-Service }\n    \"start\" { Start-Service }\n    \"stop\" { Stop-Service }\n    \"edit\" { Edit-Service }\n    \"remove\" { Remove-Service }\n    \"help\" { Show-Help }\n    default {\n        Write-Error \"Unknown command: $Command\"\n        Show-Help\n        exit 1\n    }\n}\n